-- Sample data for the staging database (thewatch-staging), the one Pages preview deployments read.
-- Handcrafted and fictional: made up organizers and employers on example.test hosts, no subscribers, no reminders and
-- no real person's email address anywhere. Dates are relative to the day the file is loaded, so the calendar always has
-- upcoming events; reload it when they have gone by.
--
-- Load after the migrations, from the repo root:
--   npx wrangler d1 migrations apply thewatch-staging --remote --env preview
--   npx wrangler d1 execute thewatch-staging --remote --env preview --file tools/staging/seed.sql
-- Every statement is idempotent (guarded by slug or URL), so loading it twice adds nothing.
--
-- Cities: San Diego comes from migration 0008; Dallas is added here; "Virtual" is not a cities row but the events filed
-- under city = 'virtual', which is how the live site lists online sessions.

INSERT OR IGNORE INTO cities (slug, name, title, region, timezone, description, empty_copy, newsletter, sort) VALUES
('dallas', 'Dallas', 'The Watch Dallas', 'Dallas, Fort Worth and North Texas', 'America/Chicago',
 'Every cybersecurity, AI security, privacy and audit event in Dallas, Fort Worth and North Texas, in one calendar.',
 'Nothing published yet. Organizers can submit events and they appear here once approved.', 'sunday', 60);
UPDATE cities SET active = 0 WHERE slug = 'sanjose'; -- keep the staging calendar to two cities

