WITH c (city, org_slug, employer, title, url, location, remote, seniority, topics, salary, posted_offset, expires_offset, source, source_key, excerpt) AS (VALUES
  ('sandiego', 'staging-example-aerospace', 'Example Aerospace', 'Senior Security Engineer', 'https://careers.example-aerospace.test/jobs/1001', 'San Diego, CA', 'onsite', 'practitioner', '["cloud","appsec"]', '$150,000 - $190,000', '-3 days', '+27 days', 'sweep', '1001', 'You will design and run the controls that protect flight software builds. You will partner with platform engineering on secure pipelines.'),
  ('sandiego', 'staging-example-aerospace', 'Example Aerospace', 'Information Systems Security Officer (ISSO)', 'https://careers.example-aerospace.test/jobs/1002', 'San Diego, CA', 'onsite', 'practitioner', '["grc"]', NULL, '-6 days', '+24 days', 'sweep', '1002', 'You will maintain the security posture of classified systems and keep the authorization package current.'),
  ('sandiego', 'staging-example-aerospace', 'Example Aerospace', 'Security Operations Analyst I', 'https://careers.example-aerospace.test/jobs/1003', 'Poway, CA', 'onsite', 'early_career', '["threat_intel"]', '$75,000 - $95,000', '-1 days', '+29 days', 'sweep', '1003', 'You will triage alerts on the day shift and learn the detection stack from the senior analysts.'),
  ('sandiego', 'staging-placeholder-bank', 'Placeholder Bank', 'Cloud Security Architect', 'https://careers.placeholder-bank.test/roles/2001', 'San Diego, CA or Remote', 'hybrid', 'practitioner', '["cloud","identity"]', '$180,000 - $220,000', '-8 days', '+22 days', 'manual', NULL, 'You will set the cloud security standards for the bank''s move to a multi account AWS estate.'),
  ('sandiego', 'staging-placeholder-bank', 'Placeholder Bank', 'Director, Information Security', 'https://careers.placeholder-bank.test/roles/2002', 'San Diego, CA', 'hybrid', 'director', '["leadership","grc"]', NULL, '-12 days', '+18 days', 'manual', NULL, 'You will lead a team of fourteen across security engineering, operations and governance.'),
  ('dallas', 'staging-sample-health', 'Sample Health Systems', 'Privacy Analyst', 'https://careers.sample-health.test/jobs/3001', 'Dallas, TX', 'onsite', 'practitioner', '["privacy"]', '$80,000 - $100,000', '-2 days', '+28 days', 'sweep', 'R3001', 'You will run privacy impact assessments for new clinical systems and answer patient access requests.'),
  ('dallas', 'staging-sample-health', 'Sample Health Systems', 'IT Audit Manager', 'https://careers.sample-health.test/jobs/3002', 'Irving, TX', 'hybrid', 'manager', '["audit","grc"]', NULL, '-5 days', '+25 days', 'sweep', 'R3002', 'You will plan and lead the annual IT audit calendar and present findings to the audit committee.'),
